import { PARAMETERS, PARAM_BY_ID, PRESETS, DEFAULT_ROUTES, makeDocument, validateDocument, normalize, denormalize, formatValue, duration, noteName } from './model.js';
import { Store } from './state.js';
import { NativeAudioEngine, encodeWav } from './audio/engine.js';
import { SculptureRenderer } from './visual/sculpture.js';
import { MappingEditor } from './ui/mapping.js';
import { ContourView } from './ui/contour.js';

const $=selector=>document.querySelector(selector);
const store=new Store(),audio=new NativeAudioEngine(),renderer=new SculptureRenderer($('#sculpture')),miniRenderer=new SculptureRenderer($('#mini-sculpture')),contour=new ContourView($('#envelope-canvas'));
const mapping=new MappingEditor(store);
let mode='sculpt',group='source',loadedPreset=PRESETS.find(p=>p.name===store.document.name)||null,activeEvent=null,looping=false,loopTimer=null,compare=false,playingPromise=false,playbackTicket=0,toastTimer=null,frameTime=0;
const inputs=new Map();
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3600);}
function makeControls(){const container=$('#parameter-controls');container.replaceChildren();inputs.clear();for(const p of PARAMETERS.filter(p=>p.group===group)){const wrapper=document.createElement('div');wrapper.className='parameter-control';const row=document.createElement('div');row.className='control-label';const label=document.createElement('label');label.htmlFor=`param-${p.id}`;label.textContent=p.label;const output=document.createElement('output');output.htmlFor=`param-${p.id}`;const input=document.createElement('input');input.type='range';input.id=`param-${p.id}`;input.min=0;input.max=1000;input.step=1;input.setAttribute('aria-label',p.label);input.title=p.description;const ends=document.createElement('div');ends.className='range-ends';const low=document.createElement('span'),high=document.createElement('span');low.textContent=formatValue(p.id,p.min);high.textContent=formatValue(p.id,p.max);ends.append(low,high);row.append(label,output);wrapper.append(row,input,ends);container.append(wrapper);inputs.set(p.id,{input,output,wrapper});input.addEventListener('input',()=>{const value=denormalize(p.id,Number(input.value)/1000);store.edit(doc=>{doc.params[p.id]=value;},'parameter');wrapper.classList.add('active');$('#parameter-note').textContent=p.description;});input.addEventListener('change',()=>{store.commit();wrapper.classList.remove('active');if(looping)scheduleNext(true);});input.addEventListener('focus',()=>{$('#parameter-note').textContent=p.description;});input.addEventListener('pointerenter',()=>{$('#parameter-note').textContent=p.description;});input.addEventListener('dblclick',()=>{store.transaction(doc=>{doc.params[p.id]=store.initial.params[p.id];},'parameter');});}}
function syncControls(){for(const [id,{input,output}]of inputs){const value=store.document.params[id],n=normalize(id,value);input.value=n*1000;input.style.setProperty('--fill',`${n*100}%`);input.setAttribute('aria-valuetext',formatValue(id,value));output.textContent=formatValue(id,value);}}
const thumbnailPaths={origin:'M4 16 H116',velvet:'M4 16 Q30 3 61 4 Q88 5 116 16 M4 16 Q30 29 61 28 Q88 26 116 16 M4 16 Q50 0 116 16 M4 16 Q50 32 116 16 M4 16 H116 M4 16 Q70 5 116 16 M4 16 Q70 27 116 16',reese:'M4 16 Q20 4 33 13 T60 13 T88 13 T116 16 M4 16 Q20 28 33 19 T60 19 T88 19 T116 16 M4 16 Q40 -2 76 18 T116 16 M4 16 Q40 34 76 14 T116 16 M4 16 H116',bell:'M4 16 Q18 -2 40 10 T116 16 M4 16 Q18 34 40 22 T116 16 M4 16 H116 M38 16 Q45 7 60 12 T116 16 M38 16 Q45 25 60 20 T116 16 M65 16 Q74 8 116 16',cloud:'M4 16 L8 14 L12 17 L16 11 L20 19 L24 8 L28 22 L32 11 L36 25 L40 6 L44 24 L48 8 L52 28 L56 4 L60 25 L64 7 L68 22 L72 9 L76 25 L80 13 L84 22 L88 12 L92 20 L96 13 L100 18 L104 14 L108 17 L116 16 M4 16 H116'};
function renderPresets(){const cards=$('#preset-cards');cards.replaceChildren();PRESETS.forEach((preset,i)=>{const button=document.createElement('button');button.className='preset-card';button.dataset.preset=preset.id;button.title=preset.description;button.setAttribute('aria-label',`Load ${preset.name}, ${preset.family}`);button.innerHTML=`<svg viewBox="0 0 120 32" aria-hidden="true"><path d="${thumbnailPaths[preset.id]}"/></svg><span class="preset-number">0${i+1}</span><span>${preset.name}</span>`;button.addEventListener('click',()=>loadPreset(preset));cards.append(button);});}
function loadPreset(preset){stop();loadedPreset=preset;mapping.selected=null;store.load(makeDocument(preset));renderer.resetView();miniRenderer.resetView();toast(`${preset.name} loaded`);}
function renderHeader(){const doc=store.document;$('#preset-title').firstChild.textContent=doc.name;const factory=loadedPreset&&loadedPreset.name===store.initial.name;$('#preset-family').textContent=factory?loadedPreset.family.toUpperCase():'YOUR EXPLORATION';$('#preset-description').textContent=factory?loadedPreset.description:'An exploration in sound and form. Make it your own.';$('#modified-indicator').hidden=JSON.stringify(doc.params)===JSON.stringify(store.initial.params)&&JSON.stringify(doc.routes)===JSON.stringify(store.initial.routes);for(const card of document.querySelectorAll('.preset-card')){const active=card.dataset.preset===loadedPreset?.id;card.classList.toggle('active',active);card.setAttribute('aria-pressed',active);}const p=doc.params;$('#note-label').textContent=noteName(p.pitch);$('#pitch-label').textContent=formatValue('pitch',p.pitch);const d=duration(p);$('#duration-label').textContent=`${d.toFixed(2)} s`;$('#timeline-end').textContent=d.toFixed(2);$('#route-count').textContent=doc.routes.length;$('#saved-count').textContent=store.saved.length;$('#undo-button').disabled=!store.undoStack.length;$('#redo-button').disabled=!store.redoStack.length;}
function sync(doc,kind){renderer.setDocument(doc,kind==='load');miniRenderer.setDocument(doc,kind==='load');syncControls();renderHeader();contour.setParams(doc.params);mapping.update();if(kind==='load'||kind==='routes')mapping.renderDetails();}
store.subscribe(sync);makeControls();renderPresets();sync(store.document,'load');

async function play(){if(playingPromise)return;playingPromise=true;const ticket=playbackTicket;try{if(!looping)audio.stop();const params=compare?store.initial.params:store.document.params;const event=await audio.trigger(params);if(document.hidden||ticket!==playbackTicket){audio.disposeVoice(event);return;}activeEvent=event;renderer.trigger(event);miniRenderer.trigger(event);$('#audio-status').textContent='AUDIO RUNNING';if(looping)scheduleNext();}catch(e){toast(e.message||'Audio could not start. Try pressing Play again.');$('#audio-status').textContent='AUDIO UNAVAILABLE';}finally{playingPromise=false;}}
function scheduleNext(immediate=false){clearTimeout(loopTimer);if(!looping)return;const interval=immediate?60:(duration(store.document.params)+.18)*1000;loopTimer=setTimeout(()=>play(),interval);}
function stop(){playbackTicket++;clearTimeout(loopTimer);loopTimer=null;audio.stop();activeEvent=null;renderer.stop();miniRenderer.stop();setLoop(false);$('#audio-status').textContent='READY WHEN YOU ARE';}
function setLoop(value){looping=value;$('#loop-button').classList.toggle('active',value);$('#loop-button').setAttribute('aria-pressed',value);if(!value){clearTimeout(loopTimer);loopTimer=null;}}
$('#play-button').addEventListener('click',play);$('#stop-button').addEventListener('click',stop);$('#loop-button').addEventListener('click',()=>{setLoop(!looping);if(looping)play();});$('#mute-button').addEventListener('click',()=>{audio.setMuted(!audio.muted);$('#mute-button').setAttribute('aria-pressed',audio.muted);$('#mute-button').setAttribute('aria-label',audio.muted?'Unmute audio':'Mute audio');});
document.querySelectorAll('[data-group]').forEach(button=>button.addEventListener('click',()=>{group=button.dataset.group;for(const b of document.querySelectorAll('[data-group]')){b.classList.toggle('active',b===button);b.setAttribute('aria-selected',b===button);}makeControls();syncControls();$('#parameter-note').textContent={source:'Change a quality. The sound updates on the next play.',contour:'The outline of a sound, from first breath to last.',space:'A sound and the impressions it leaves behind.'}[group];}));
document.querySelectorAll('[data-mode]').forEach(button=>button.addEventListener('click',()=>{mode=button.dataset.mode;for(const b of document.querySelectorAll('[data-mode]')){b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',b===button);}$('#sculpt-workspace').hidden=mode!=='sculpt';$('#mapping-workspace').hidden=mode!=='mapping';$('#sound-inspector').hidden=mode!=='sculpt';$('#route-inspector').hidden=mode!=='mapping';if(mode==='mapping'){mapping.update();mapping.renderDetails();miniRenderer.resize();}else renderer.resize();}));
$('#front-view').addEventListener('click',()=>{renderer.frontView();$('#view-label').textContent='FRONT VIEW';});$('#reset-view').addEventListener('click',()=>{renderer.resetView();$('#view-label').textContent='PERSPECTIVE';});$('#sculpture').addEventListener('pointermove',e=>{if(e.buttons)$('#view-label').textContent='PERSPECTIVE';});$('#sculpture').addEventListener('dblclick',()=>{$('#view-label').textContent='PERSPECTIVE';});
$('#undo-button').addEventListener('click',()=>store.undo());$('#redo-button').addEventListener('click',()=>store.redo());$('#reset-sound').addEventListener('click',()=>{stop();store.transaction(()=>{store.document=structuredClone(store.initial);},'load');toast('Sound restored to its loaded state');});$('#reset-mappings').addEventListener('click',()=>{mapping.selected=null;store.transaction(doc=>{doc.routes=structuredClone(DEFAULT_ROUTES);},'routes');toast('Default connections restored');});
function beginCompare(){if(compare)return;compare=true;$('#compare-button').classList.add('comparing');$('#compare-button').textContent='Original sound ↔';renderer.setCompare(store.initial);miniRenderer.setCompare(store.initial);}
function endCompare(){if(!compare)return;compare=false;$('#compare-button').classList.remove('comparing');$('#compare-button').textContent='Hold to compare ↔';renderer.setCompare(null);miniRenderer.setCompare(null);}
$('#compare-button').addEventListener('pointerdown',e=>{e.currentTarget.setPointerCapture(e.pointerId);beginCompare();});$('#compare-button').addEventListener('pointerup',endCompare);$('#compare-button').addEventListener('pointercancel',endCompare);$('#compare-button').addEventListener('keydown',e=>{if(e.key===' '||e.key==='Enter'){e.preventDefault();beginCompare();}});$('#compare-button').addEventListener('keyup',endCompare);$('#compare-button').addEventListener('blur',endCompare);

$('#help-button').addEventListener('click',()=>$('#help-dialog').showModal());document.querySelectorAll('[data-close-dialog]').forEach(button=>button.addEventListener('click',()=>document.getElementById(button.dataset.closeDialog).close()));for(const dialog of document.querySelectorAll('dialog'))dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
$('#save-button').addEventListener('click',()=>{$('#save-name').value=store.document.name;$('#save-dialog').showModal();$('#save-name').select();});$('#save-form').addEventListener('submit',e=>{e.preventDefault();const name=$('#save-name').value.trim();if(!name)return;store.save(name);$('#save-dialog').close();toast(`“${name}” saved in this browser`);});
function renderLibrary(){const list=$('#library-list');list.replaceChildren();if(!store.saved.length){const p=document.createElement('p');p.className='library-empty';p.textContent='Your saved sounds will appear here. Explore a preset, change its qualities, then choose Save sound.';list.append(p);return;}store.saved.forEach((doc,i)=>{const row=document.createElement('div');row.className='saved-row';const load=document.createElement('button');load.textContent=doc.name;const meta=document.createElement('small');meta.textContent=`${formatValue('pitch',doc.params.pitch)} · ${duration(doc.params).toFixed(2)} s · ${doc.routes.length} connections`;load.append(meta);load.addEventListener('click',()=>{stop();loadedPreset=null;store.load(doc);$('#library-dialog').close();toast(`${doc.name} loaded`);});const exportButton=document.createElement('button');exportButton.textContent='JSON ↓';exportButton.setAttribute('aria-label',`Export ${doc.name}`);exportButton.addEventListener('click',()=>downloadJSON(doc));row.append(load,exportButton);list.append(row);});}
$('#library-button').addEventListener('click',()=>{renderLibrary();$('#library-dialog').showModal();});
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}
const filename=name=>(name.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')||'sound');
function downloadJSON(doc=store.document){download(new Blob([JSON.stringify(doc,null,2)],{type:'application/json'}),`${filename(doc.name)}.soundform.json`);toast('Sound and connections exported');}
$('#export-button').addEventListener('click',()=>downloadJSON());$('#import-button').addEventListener('click',()=>$('#import-file').click());$('#import-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>500000)throw new Error('Preset files must be smaller than 500 KB.');const doc=validateDocument(JSON.parse(await file.text()));stop();loadedPreset=null;store.load(doc);toast(`${doc.name} imported`);}catch(error){toast(error instanceof SyntaxError?'This file does not contain valid JSON.':error.message);}finally{e.target.value='';}});
$('#wav-button').addEventListener('click',async()=>{const button=$('#wav-button');button.disabled=true;button.textContent='Rendering…';const doc=structuredClone(store.document);try{const buffer=await audio.render(doc.params);download(encodeWav(buffer),`${filename(doc.name)}.wav`);toast('Stereo WAV rendered with effects');}catch(e){toast(`Could not render audio: ${e.message}`);}finally{button.disabled=false;button.textContent='WAV ↓';}});

document.addEventListener('keydown',e=>{const editable=e.target.matches('input,textarea,select,[contenteditable=true]'),dialog=document.querySelector('dialog[open]');if(e.key==='Escape'){if(!dialog){stop();mapping.cancel();}return;}if(dialog||editable)return;const mod=e.metaKey||e.ctrlKey;if(mod&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?store.redo():store.undo();return;}if(e.code==='Space'&&e.target.tagName!=='BUTTON'&&e.target.getAttribute('role')!=='button'){e.preventDefault();if(!e.repeat)play();}if(e.key.toLowerCase()==='l'&&!mod){e.preventDefault();setLoop(!looping);if(looping)play();}});
document.addEventListener('visibilitychange',()=>{if(document.hidden)stop();});
function animate(ms){const now=audio.context?audio.now():ms/1000;const playing=activeEvent&&now>=activeEvent.start&&now-activeEvent.start<activeEvent.total;renderer.draw(now);if(mode==='mapping')miniRenderer.draw(now);if(ms-frameTime>30){frameTime=ms;const elapsed=playing?Math.max(0,now-activeEvent.start):0;$('#play-button').classList.toggle('playing',!!playing);$('.state-dot').classList.toggle('playing',!!playing);$('#stage-state').textContent=playing?'SOUND IN MOTION':compare?'ORIGINAL FORM':'STATIC FORM';if(playing){const minutes=Math.floor(elapsed/60).toString().padStart(2,'0'),seconds=(elapsed%60).toFixed(2).padStart(5,'0');$('#transport-time').textContent=`${minutes}:${seconds}`;contour.draw(elapsed/activeEvent.duration);}else{$('#transport-time').textContent='00:00.00';contour.draw();if(!looping)$('#audio-status').textContent=audio.muted?'AUDIO MUTED':'READY WHEN YOU ARE';}}requestAnimationFrame(animate);}
requestAnimationFrame(animate);
